// 🎯 笔记管理器核心逻辑
var notes = [];

function addNote(title, content) {
  notes.push({
    time: new Date().toISOString(),
    title: title,
    content: content
  });
  console.log('✅ 笔记已添加:', title);
}

function listNotes() {
  console.log('📋 共 ' + notes.length + ' 条笔记:');
  notes.forEach(function(n, i) {
    console.log('  [' + (i+1) + ']', n.title, '-', n.time.slice(0,10));
  });
}

