// 🎯 模拟图书API服务器
var books = [
  {id:1,title:'JavaScript高级编程',author:'Nicholas'},
  {id:2,title:'深入浅出Node.js',author:'朴灵'},
  {id:3,title:'ES6标准入门',author:'阮一峰'}
];

function handleGET(url) {
  if (url === '/books') {
    console.log('📚 返回所有图书:', JSON.stringify(books));
  } else if (url.startsWith('/books?id=')) {
    var id = parseInt(url.split('=')[1]);
    var book = books.find(function(b){return b.id===id});
    console.log('📖 返回单本图书:', JSON.stringify(book || {error:'未找到'}));
  }
}

handleGET('/books?id=1');
handleGET('/books');
console.log('\n💡 在Node中换成http.createServer实现!');

